static bool al_kw_binsearch(const char *word, const char *const *arr, size_t count) {
  size_t lo = 0;
  size_t hi = count;
  while (lo < hi) {
    size_t mid = lo + (hi - lo) / 2;
    int cmp = strcmp(word, arr[mid]);
    if (cmp == 0) return true;
    if (cmp < 0) hi = mid; else lo = mid + 1;
  }
  return false;
}

